create table reserve_funds (balance numeric(15,2) not null, apartment_id bigint not null, id bigint generated by default as identity, last_updated timestamp(6), fund_type varchar(255) not null check ((fund_type in ('CORPUS','SINKING','EMERGENCY','MAINTENANCE_RESERVE'))), primary key (id), unique (apartment_id, fund_type));
alter table if exists reserve_funds add constraint FK3axb0t8lqupmwbq7ren2mjemb foreign key (apartment_id) references apartments;
